const fallback={customer:{name:envelope.context?.customer?.name??envelope.context?.lead?.name??null,email:email??envelope.context?.customer?.email??envelope.context?.lead?.email??null,phone:envelope.context?.customer?.phone??envelope.context?.lead?.phone??envelope.event?.sender??null},vehicle:{vin:vin??envelope.context?.lead?.vin??null,year:envelope.context?.lead?.year??null,make:envelope.context?.lead?.make??null,model:envelope.context?.lead?.model??null},language:{code:'en',name:'English',confidence:0},inquiry:{category:currentCategory??'General Inquiry',confidence:'Low'},journey:{intent:journeyIntent,sentiment:(optOut||notInterested||visitReject||upset)?'Negative':'Neutral'},business_flow:service?'SERVICE':currentCategory&&currentCategory!=='General Inquiry'?'SALES':'UNKNOWN',communication:{preferred_mode:/\bemail\b/i.test(msg)?'email':'unknown',email_present:!!email},dnd:{requested:optOut,reason:optOut?'opt_out':null},escalation:{required:humanRequest||callback||urgent||upset,reason:humanRequest?'human_or_salesperson_request':callback?'callback_request':urgent?'urgent_need':upset?'upset_or_complaint':null,callback_requested:callback},appointment:{signal:appointmentSignal,date:null,time:null},response_signals:{asks_location:/\b(where|address|location|directions)\b/i.test(msg),asks_booking_link:/\b(where|how|link)\b.*\b(book|appointment|schedule)\b/i.test(msg),asks_vdp_content:/\b(photo|picture|video|interior|exterior|feature|trim|accessor|carfax|autocheck|listing|spec|more info|more detail)\b/i.test(msg),complex_trade:/\b(kbb|trade.?in|loan payoff|appraisal)\b/i.test(msg),complex_finance:/\b(apr|zero down|cosigner|finance application|credit application)\b/i.test(msg),explicit_visit_refusal:visitReject,closure:/^(thanks|thank you|ok|okay|bye|got it)[!. ]*$/i.test(msg.trim())}};
