const coalesceFields=(model,known,fields)=>Object.fromEntries(fields.map(field=>[field,model?.[field]??known?.[field]??null]));
intel.customer=coalesceFields(intel.customer,fallback.customer,['name','email','phone']);intel.vehicle=coalesceFields(intel.vehicle,fallback.vehicle,['vin','year','make','model']);intel.language={...fallback.language,...(intel.language??{})};intel.inquiry={...fallback.inquiry,...(intel.inquiry??{})};intel.journey={...fallback.journey,...(intel.journey??{})};intel.communication={...fallback.communication,...(intel.communication??{})};intel.response_signals={...fallback.response_signals,...(intel.response_signals??{})};
