intel.journey.intent=journeyIntent;
intel.business_flow=service?'SERVICE':intel.inquiry.category==='General Inquiry'?'UNKNOWN':'SALES';
intel.dnd={requested:optOut,reason:optOut?'opt_out':null};
intel.escalation={required:humanRequest||callback||urgent||upset,reason:humanRequest?'human_or_salesperson_request':callback?'callback_request':urgent?'urgent_need':upset?'upset_or_complaint':null,callback_requested:callback};
